B.abt=s(["\u0986\u09aa\u09a1\u09c7\u099f \u09b8\u09cd\u0995\u09cd\u09b0\u09bf\u09a8 \u09a0\u09bf\u0995 \u0995\u09b0\u09be \u09b9\u09af\u09bc\u09c7\u099b\u09c7 \u2014 \u09a8\u09a4\u09c1\u09a8 \u0986\u09aa\u09a1\u09c7\u099f \u098f\u09b2\u09c7\u0987 \u098f\u09ac\u09be\u09b0 \u0987\u09a8\u09b8\u09cd\u099f\u09b2\u09c7\u09b0 \u0986\u0997\u09c7\u0987 \u09b8\u09c7\u0987 \u0986\u09aa\u09a1\u09c7\u099f\u09c7\u09b0 \u09a8\u09bf\u099c\u09c7\u09b0 \u09a8\u09cb\u099f \u09a6\u09c7\u0996\u09a4\u09c7 \u09aa\u09be\u09ac\u09c7\u09a8, \u0986\u0997\u09c7\u09b0 \u09ad\u09be\u09b0\u09cd\u09b8\u09a8\u09c7\u09b0\u099f\u09be \u09a8\u09af\u09bc\u0964","\u098f\u0987 \u09a8\u09cb\u099f\u099f\u09be\u0987 \u09a4\u09be\u09b0 \u09aa\u09cd\u09b0\u09ae\u09be\u09a3 \u2014 \u098f\u0996\u09a8 \u09a5\u09c7\u0995\u09c7 \u09aa\u09cd\u09b0\u09a4\u09bf\u099f\u09bf \u09b0\u09bf\u09b2\u09bf\u099c\u09c7\u09b0 \u09a8\u09cb\u099f \u09a8\u09bf\u099c\u09c7 \u09a5\u09c7\u0995\u09c7\u0987 \u0986\u09aa\u09a8\u09be\u09b0 \u09ab\u09cb\u09a8\u09c7 \u09aa\u09cc\u0981\u099b\u09c7 \u09af\u09be\u09ac\u09c7\u0964","\u0985\u09cd\u09af\u09be\u09aa \u0986\u09b0\u0993 \u09ae\u09b8\u09c3\u09a3 \u0995\u09b0\u09a4\u09c7 \u099b\u09cb\u099f\u0996\u09be\u099f\u09cb \u09a0\u09bf\u0995\u09a0\u09be\u0995 \u0993 \u09aa\u09be\u09b2\u09bf\u09b6\u0964"],t.s)
B.akU=s(["\u0905\u092a\u0921\u0947\u091f \u0938\u094d\u0915\u094d\u0930\u0940\u0928 \u0920\u0940\u0915 \u0915\u0940 \u0917\u0908 \u2014 \u0928\u092f\u093e \u0905\u092a\u0921\u0947\u091f \u0924\u0948\u092f\u093e\u0930 \u0939\u094b\u0924\u0947 \u0939\u0940 \u0905\u092c \u0907\u0902\u0938\u094d\u091f\u0949\u0932 \u0938\u0947 \u092a\u0939\u0932\u0947 \u0909\u0938\u0940 \u0905\u092a\u0921\u0947\u091f \u0915\u0947 \u0928\u094b\u091f \u0926\u093f\u0916\u0947\u0902\u0917\u0947, \u092a\u093f\u091b\u0932\u0947 \u0935\u0930\u094d\u0936\u0928 \u0915\u0947 \u0928\u0939\u0940\u0902\u0964","\u092f\u0939 \u0928\u094b\u091f \u0939\u0940 \u0907\u0938\u0915\u093e \u0938\u092c\u0942\u0924 \u0939\u0948 \u2014 \u0905\u092c \u0938\u0947 \u0939\u0930 \u0930\u093f\u0932\u0940\u091c\u093c \u0915\u0947 \u0928\u094b\u091f \u0905\u092a\u0928\u0947 \u0906\u092a \u0906\u092a\u0915\u0947 \u092b\u093c\u094b\u0928 \u0924\u0915 \u092a\u0939\u0941\u0901\u091a\u0947\u0902\u0917\u0947\u0964","\u0910\u092a \u0915\u094b \u0914\u0930 \u0938\u0939\u091c \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u091b\u094b\u091f\u0947 \u0938\u0941\u0927\u093e\u0930 \u0914\u0930 \u092a\u0949\u0932\u093f\u0936\u0964"],t.s)
